function findPair(list1, list2, target) {
  for (const a of list1) {
    for (const b of list2) {
      if (a + b === target) {
        return [a, b];
      }
    }
  }
  return null;
}

console.log(findPair([1, 3, 5], [2, 4, 6], 9));

